use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn handle_explain (early_dcx : & EarlyDiagCtxt , registry : Registry , code : & str , color : ColorConfig ,) { let upper_cased_code = code . to_ascii_uppercase () ; if let Ok (code) = upper_cased_code . trim_prefix ('E') . parse :: < u32 > () && code <= ErrCode :: MAX_AS_U32 && let Ok (description) = registry . try_find_description (ErrCode :: from_u32 (code)) { let mut is_in_code_block = false ; let mut text = String :: new () ; for line in description . lines () { let indent_level = line . find (| c : char | ! c . is_whitespace ()) . unwrap_or (line . len ()) ; let dedented_line = & line [indent_level ..] ; if dedented_line . starts_with ("```") { is_in_code_block = ! is_in_code_block ; text . push_str (& line [.. (indent_level + 3)]) ; } else if is_in_code_block && dedented_line . starts_with ("# ") { continue ; } else { text . push_str (line) ; } text . push ('\n') ; } if io :: stdout () . is_terminal () { show_md_content_with_pager (& text , color) ; } else { safe_print ! ("{text}") ; } } else { early_dcx . early_fatal (format ! ("{code} is not a valid error code")) ; } }